export const SKIP_FORMATS = [
  'org.nspasteboard.ConcealedType',
  'org.nspasteboard.TransientType',
  'org.nspasteboard.AutoGeneratedType',
  'com.agilebits.onepassword',
] as const;

const SKIP_LOWER = new Set(SKIP_FORMATS.map((f) => f.toLowerCase()));
const TEXT_FORMATS = new Set(['text/plain', 'public.utf8-plain-text', 'nspasteboardtypestring', 'string']);

export type SkipReason = 'concealed' | 'empty' | 'too-long' | 'unchanged' | 'own-write' | 'blocked';

export type ClipDecision = { kind: 'capture'; text: string } | { kind: 'skip'; reason: SkipReason };

export interface ClassifyInput {
  formats: readonly string[];
  /** Null when the text has not been read. Never read when `formats` contains a concealed type. */
  text: string | null;
  last: string | null;
  ownWrite: string | null;
  maxChars: number;
}

export function hasSkipFormat(formats: readonly string[]): boolean {
  return formats.some((f) => SKIP_LOWER.has(f.toLowerCase()));
}

export function hasTextFormat(formats: readonly string[]): boolean {
  return formats.some((f) => TEXT_FORMATS.has(f.toLowerCase()));
}

export function classifyClip(input: ClassifyInput): ClipDecision {
  const { formats, text, last, ownWrite, maxChars } = input;
  if (hasSkipFormat(formats)) return { kind: 'skip', reason: 'concealed' };
  if (text === null || text.trim().length === 0) return { kind: 'skip', reason: 'empty' };
  if (text.length > maxChars) return { kind: 'skip', reason: 'too-long' };
  if (ownWrite !== null && text === ownWrite) return { kind: 'skip', reason: 'own-write' };
  if (last !== null && text === last) return { kind: 'skip', reason: 'unchanged' };
  return { kind: 'capture', text };
}

/** Single-line preview, cut on a code point boundary. */
export function makePreview(text: string, max = 80): string {
  const flat = text.replace(/\s+/g, ' ').trim();
  const points = Array.from(flat);
  if (points.length <= max) return flat;
  return `${points.slice(0, max).join('').trimEnd()}…`;
}

type MaybePromise<T> = T | Promise<T>;

export interface ClipboardAdapter {
  formats(): MaybePromise<string[]>;
  readText(): MaybePromise<string>;
}

export interface WatcherTimers {
  setInterval(fn: () => void, ms: number): unknown;
  clearInterval(handle: unknown): void;
}

export type WatcherStatus = 'watching' | 'blocked';

export interface ClipboardWatcherDeps {
  adapter: ClipboardAdapter;
  isLauncherFocused(): boolean;
  onCapture(text: string): void;
  onStatus(status: WatcherStatus): void;
  maxChars: number;
  intervalMs?: number;
  timers?: WatcherTimers;
  now?(): number;
}

export interface ClipboardWatcher {
  /** Resolves once the baseline read (the access check) finished. Never rejects. */
  start(): Promise<void>;
  stop(): void;
  isRunning(): boolean;
  markOwnWrite(text: string): void;
  recheck(): Promise<WatcherStatus>;
  tick(): Promise<void>;
}

export const OWN_WRITE_TTL_MS = 2000;

interface Probe {
  text: string | null;
  /** True when a text format is present but the read came back empty (macOS denied access). */
  emptyRead: boolean;
  concealed: boolean;
}

export function createClipboardWatcher(deps: ClipboardWatcherDeps): ClipboardWatcher {
  const { adapter, isLauncherFocused, onCapture, onStatus, maxChars } = deps;
  const intervalMs = deps.intervalMs ?? 500;
  const now = deps.now ?? Date.now;
  const timers: WatcherTimers = deps.timers ?? {
    setInterval: (fn, ms) => setInterval(fn, ms),
    clearInterval: (h) => clearInterval(h as ReturnType<typeof setInterval>),
  };

  let handle: unknown = null;
  let generation = 0;
  let last: string | null = null;
  let ownWrite: { text: string; at: number } | null = null;
  let needsResync = false;
  let blocked = false;
  let busy = false;
  let starting: Promise<void> = Promise.resolve();

  /**
   * Reads the pasteboard text unless a concealed format is present before or after the read.
   * Returns null when the watcher was stopped before the read happened.
   */
  const probe = async (gen: number): Promise<Probe | null> => {
    const formats = await adapter.formats();
    if (gen !== generation) return null;
    if (hasSkipFormat(formats)) return { text: null, emptyRead: false, concealed: true };
    if (!hasTextFormat(formats)) return { text: '', emptyRead: false, concealed: false };
    const text = await adapter.readText();
    if (gen !== generation) return null;
    if (hasSkipFormat(await adapter.formats())) return { text: null, emptyRead: false, concealed: true };
    if (gen !== generation) return null;
    return { text, emptyRead: text === '', concealed: false };
  };

  const status = (): WatcherStatus => (blocked ? 'blocked' : 'watching');

  /** Returns false when the watcher was stopped meanwhile. An empty read or a throwing adapter latches `blocked`. */
  const baseline = async (gen: number): Promise<boolean> => {
    let p: Probe | null;
    try {
      p = await probe(gen);
    } catch {
      if (gen !== generation) return false;
      blocked = true;
      return true;
    }
    if (p === null) return false;
    blocked = p.emptyRead;
    if (!blocked) last = p.concealed ? null : p.text;
    return true;
  };

  const tick = async () => {
    if (handle === null || busy) return;
    busy = true;
    const gen = generation;
    try {
      await starting;
      if (gen !== generation || handle === null) return;
      if (isLauncherFocused()) {
        needsResync = true;
        return;
      }
      if (blocked) return;
      if (needsResync) {
        needsResync = false;
        if ((await baseline(gen)) && blocked) onStatus('blocked');
        return;
      }
      const p = await probe(gen);
      if (p === null || p.concealed) return;
      let own = ownWrite;
      if (own && now() - own.at > OWN_WRITE_TTL_MS) own = ownWrite = null;
      const d = classifyClip({ formats: [], text: p.text, last, ownWrite: own?.text ?? null, maxChars });
      if (p.text !== null && p.text.trim().length > 0) ownWrite = null;
      if (d.kind === 'capture') {
        last = d.text;
        onCapture(d.text);
      } else if (d.reason === 'too-long' || d.reason === 'own-write') {
        last = p.text;
      }
    } catch {
      if (gen === generation) {
        blocked = true;
        onStatus('blocked');
      }
    } finally {
      if (gen === generation) busy = false;
    }
  };

  return {
    start() {
      if (handle !== null) return starting;
      needsResync = false;
      blocked = false;
      const gen = ++generation;
      handle = timers.setInterval(() => void tick(), intervalMs);
      starting = baseline(gen).then((live) => {
        if (live) onStatus(status());
      });
      return starting;
    },
    stop() {
      if (handle !== null) timers.clearInterval(handle);
      handle = null;
      generation++;
      last = null;
      ownWrite = null;
      needsResync = false;
      blocked = false;
      busy = false;
    },
    isRunning: () => handle !== null,
    markOwnWrite(text) {
      ownWrite = { text, at: now() };
      last = text;
    },
    async recheck() {
      const gen = generation;
      if (!(await baseline(gen))) return status();
      onStatus(status());
      return status();
    },
    tick,
  };
}
